PATCH_BLOCK = r'''

# === CGC Qwen3-VL dense resume patch (auto-generated by cgc_engine) =========
# Enables cloud sglang server to resume forward from Mac-emitted hidden_P
# (layer-split reverse: Mac runs layers 0..P-1, cloud resumes P..end).
# Adapted from qwen3_resume_patch.py for Qwen3-VL dense (Qwen3LLMModel):
#   - resume dispatch lives in Qwen3LLMModel.forward (not VL wrapper),
#     because VL wrapper.forward calls language_model via general_mm_embed_routine
#     which does not thread finished_layer/hidden_states_ref through.
#   - preserves VL-specific input_deepstack_embeds + post_residual_addition
#     on layer/norm calls (deepstack behavior).
#   - dual-format payload: DOPDResumePayloadV2 (state ABI v2, unified with
#     MoE via abi_descriptor["model_type"]="dense") or legacy dict.
#   - vs MoE: dense DecoderLayer has no router/gate/expert; but at the
#     LLMModel.forward level the layer-call signature is identical to MoE,
#     so the resume injection logic is the same (state ABI convergence).
# Non-resume path delegates to the original forward (zero-invasive).
import os as _cgc_os
import sys as _cgc_sys
import threading as _cgc_threading
from contextlib import nullcontext as _cgc_nullctx

_CGC_RESUME_STEP = 0
_CGC_TRANSPORTS = {}
_CGC_TRANSPORT_LOCK = _cgc_threading.Lock()
_CGC_PATCH_MARKER = "cgc_qwen3_vl_resume_v1"
_DOPD_RESUME_PAYLOAD_MAGIC_V2 = b"CGC_DOPD_RESUME_V2\x00"
_CGC_MODEL_TYPE = "dense"  # abi_descriptor["model_type"] for dense


def _cgc_rank():
    try:
        import torch.distributed as _dist
        if _dist.is_available() and _dist.is_initialized():
            return int(_dist.get_rank())
    except Exception:
        pass
    return 0


def _cgc_load_hidden_states(ref, device, dtype):
    """Resolve a hidden-states reference into a tensor on device/dtype.

    ref may be: torch.Tensor (moved), bytes/bytearray (BytesIO load),
    str path (torch.load). Mirrors qwen3_resume_patch._cgc_load_hidden_states
    and qwen3_vl_moe_resume_patch._cgc_load_hidden_states (identical contract).
    """
    import io
    import torch
    if torch.is_tensor(ref):
        return ref.to(device=device, dtype=dtype)
    if isinstance(ref, (bytes, bytearray)):
        return torch.load(io.BytesIO(ref), map_location=device, weights_only=True)
    if isinstance(ref, str):
        return torch.load(ref, map_location=device, weights_only=True)
    raise TypeError(f"_cgc_load_hidden_states: unsupported ref type {type(ref)!r}")


def _cgc_decode_resume_payload(raw):
    """Dual-format resume payload decoder (state ABI v2 + legacy dict).

    Unified with qwen3_vl_moe_resume_patch._cgc_decode_resume_payload: same
    contract, same field names. The only difference is abi_descriptor
    populated by _cgc_normalize_dopd_dict sets model_type="dense" for dense
    (vs "moe" for MoE). Decoder is model-agnostic; consumer reads
    finished_layer + hidden_states + residual uniformly.

    Returns dict with keys:
      - finished_layer: int (>=0) or None
      - hidden_states: torch.Tensor or None
      - residual: torch.Tensor or None
      - step: int (default 0)
      - abi_descriptor: dict (from DOPD payload, may be empty)

    Accepts:
      (a) DOPDResumePayloadV2-encoded bytes (magic + canonical JSON) ->
          decode via _cgc_normalize_dopd_dict; hidden_states from state_bytes_b64
          or abi_descriptor["hidden_states_ref"] (caller-resolved by transport)
      (b) plain dict {finished_layer, hidden_states, residual, step}
      (c) dict with nested abi_descriptor (DOPD dict already decoded by transport)
    """
    import json
    import base64
    import torch

    # (a) DOPDResumePayloadV2 magic bytes
    if isinstance(raw, (bytes, bytearray)) and bytes(raw).startswith(_DOPD_RESUME_PAYLOAD_MAGIC_V2):
        try:
            body = bytes(raw)[len(_DOPD_RESUME_PAYLOAD_MAGIC_V2):]
            d = json.loads(body.decode("utf-8"))
            return _cgc_normalize_dopd_dict(d)
        except Exception as _e:
            print(f"[CGC_RESUME] WARN DOPD decode failed: {_e!r}", flush=True)
            return {"finished_layer": None, "hidden_states": None, "residual": None,
                    "step": 0, "abi_descriptor": {}, "kv_layers": None}

    # (c) dict that already looks DOPD-shaped (transport decoded it)
    if isinstance(raw, dict) and raw.get("payload_kind") == "dopd_resume":
        return _cgc_normalize_dopd_dict(raw)

    # (b) legacy plain dict
    if isinstance(raw, dict):
        _kv = raw.get("kv_layers")
        if _cgc_os.environ.get("CGC_KV_DIAG"):
            print(
                f"[CGC_KV_DIAG] decode legacy dict: kv_layers type={type(_kv).__name__} "
                f"len={len(_kv) if hasattr(_kv, '__len__') and not isinstance(_kv, (str, bytes)) else 'N/A'} "
                f"finished_layer={raw.get('finished_layer')}",
                flush=True,
            )
        return {
            "finished_layer": raw.get("finished_layer"),
            "hidden_states": raw.get("hidden_states"),
            "residual": raw.get("residual"),
            "step": int(raw.get("step", 0) or 0),
            "abi_descriptor": raw.get("abi_descriptor", {}) or {},
            # CGC KV 注入: Mac 捕獲的前 P 層 RoPE 後 K/V (list[dict] 或 None)
            "kv_layers": _kv,
        }

    return {"finished_layer": None, "hidden_states": None, "residual": None,
            "step": 0, "abi_descriptor": {}, "kv_layers": None}


def _cgc_normalize_dopd_dict(d):
    """Map DOPDResumePayloadV2 fields onto the resume-consumer contract.

    DOPDResumePayloadV2 (cgc_engine/pd/dopd_schema.py):
      - resume_position: int        -> finished_layer
      - state_bytes_b64: str        -> hidden_states (b64 torch bytes)
      - abi_descriptor: Dict        -> may carry residual_ref / step / model_type
      - transport_codec: str        -> "cq4" etc (informational)

    dense-specific: injects abi_descriptor["model_type"]="dense" if absent
    (default for dense consumer; MoE patch sets "moe"). This is the single
    ABI divergence point between dense and MoE, converged into abi_descriptor
    so the decoder stays model-agnostic.
    """
    import base64
    import io
    import torch

    abi = dict(d.get("abi_descriptor", {}) or {})
    # Default model_type to "dense" for this patch (MoE patch defaults to "moe")
    if "model_type" not in abi:
        abi["model_type"] = _CGC_MODEL_TYPE
    # dense has no MoE router; flag for consumer/health-check
    if "has_moe_router" not in abi:
        abi["has_moe_router"] = False

    finished_layer = d.get("resume_position")
    if finished_layer is None:
        finished_layer = abi.get("finished_layer")

    hs = None
    state_b64 = d.get("state_bytes_b64", "")
    if state_b64:
        try:
            hs = torch.load(
                io.BytesIO(base64.b64decode(state_b64)),
                map_location="cpu",
                weights_only=True,
            )
        except Exception as _e:
            print(f"[CGC_RESUME] WARN state_bytes_b64 decode failed: {_e!r}", flush=True)

    # hidden_states may also be carried inline by the transport (post-decode)
    if hs is None and "hidden_states" in d:
        hs = d["hidden_states"]

    residual = abi.get("residual") or abi.get("residual_ref") or d.get("residual")
    step = int(abi.get("step", 0) or 0)

    return {
        "finished_layer": int(finished_layer) if finished_layer is not None else None,
        "hidden_states": hs,
        "residual": residual,
        "step": step,
        "abi_descriptor": abi,
        # DOPD payload 不攜帶 KV (Mac→cloud KV 走 legacy dict 路徑);
        # 此處顯式 None 避免 consumer KeyError
        "kv_layers": None,
    }


def _cgc_get_resume_transport(rank, mode):
    """Cloud-side receiver transport, cached per (rank, mode).

    Identical to qwen3_vl_moe_resume_patch._cgc_get_resume_transport: same
    MacEmitHandoff(role=receiver) TCP server on CGC_MAC_EMIT_PORT+rank;
    Mac emitter PUTs hidden_P; cloud recv() pops in-process. This is the
    layer-split reverse path. Transport is model-agnostic (dense + MoE share).

    mac_emit: MacEmitHandoff(role=receiver) — TCP server on
              CGC_MAC_EMIT_PORT+rank; Mac emitter PUTs hidden_P; cloud recv()
              pops in-process. This is the layer-split reverse path.
    file:     None — caller falls back to torch.load of the step file.
    """
    _key = ("resume_recv", int(rank), str(mode))
    if _key not in _CGC_TRANSPORTS:
        with _CGC_TRANSPORT_LOCK:
            if _key not in _CGC_TRANSPORTS:
                if mode == "mac_emit":
                    _port = int(_cgc_os.environ.get("CGC_MAC_EMIT_PORT", "31010")) + int(rank)
                    _dir = _cgc_os.path.dirname(_cgc_os.path.abspath(__file__))
                    if _dir not in _cgc_sys.path:
                        _cgc_sys.path.insert(0, _dir)
                    from cgc_handoff_transport import HandoffTransport as _HT
                    _CGC_TRANSPORTS[_key] = _HT.make(
                        "mac_emit",
                        role="receiver",
                        host="0.0.0.0",
                        port=_port,
                        connect_host=_cgc_os.environ.get(
                            "CGC_MAC_EMIT_CLOUD_HOST", "127.0.0.1"
                        ),
                    )
                    print(
                        f"[CGC_RESUME] mac_emit receiver ready on 0.0.0.0:{_port} "
                        f"rank={rank} (dense)", flush=True,
                    )
                else:
                    _CGC_TRANSPORTS[_key] = None  # file mode
    return _CGC_TRANSPORTS[_key]


# Save originals so the non-resume path is a zero-invasive delegate.
_Qwen3LLMModel_forward_orig = Qwen3LLMModel.forward


def _cgc_inject_prefill_kv(self, forward_batch, mac_kv_layers, resume_cut):
    """把 Mac 捕獲的前 P 層 KV 注入 sglang KV cache (layer 0..resume_cut)。

    修 step8 KV cache 崩:cloud resume 跳過前 P 層 forward → KV cache layer 0..P-1
    空槽 → kvcache.cuh:177 assert。本函數在 layer loop 前,用 Mac 捕獲的 RoPE 後
    K/V 補滿前 P 層 KV cache,使 layer P..end 的 attention 能正確讀取前 P 層 KV。

    Args:
      self: Qwen3LLMModel 實例 (有 .layers)
      forward_batch: sglang ForwardBatch (有 .model_runner.token_to_kv_pool, .out_cache_loc)
      mac_kv_layers: list[dict] 長度 ≥ resume_cut+1, 每項
                     {"k": torch(seq, n_kv_heads*head_dim), "v": torch(...)} 或 None。
                     None 項表該層捕獲失敗, 跳過 (該層 KV 維持空, attention 可能讀垃圾值)。
      resume_cut: int, Mac 已完成的 layer idx (注入 0..resume_cut 共 resume_cut+1 層)

    只在 EXTEND 注入; decode 時前 P 層 KV 已在 pool (方案 B: decode loop_start=0 待後續)。
    設計見 CGC_Phase2/kv_injection_design.md §4。
    """
    if not mac_kv_layers:
        return
    # 类型守卫: 防止 kv_layers 被错误地序列化成 int/其它标量 (step8 bug 诊断)
    if not isinstance(mac_kv_layers, (list, tuple)):
        print(
            f"[CGC_KV_INJECT] WARN mac_kv_layers type={type(mac_kv_layers).__name__} "
            f"(expected list/tuple), skip injection. value={mac_kv_layers!r:.200}",
            flush=True,
        )
        return
    if forward_batch is None:
        return
    # 只 EXTEND 注入 (decode 時前 P 層 KV 已在 pool; decode 增量 KV 同步難, 方案 B 待後續)
    try:
        _is_extend = bool(forward_batch.forward_mode.is_extend())
    except Exception:
        _is_extend = False
    if not _is_extend:
        return
    # sglang 标准方式: get_token_to_kv_pool() (forward_context), 不是 forward_batch.model_runner
    try:
        from sglang.srt.model_executor.forward_context import get_token_to_kv_pool
        kv_pool = get_token_to_kv_pool()
    except Exception:
        kv_pool = getattr(
            getattr(forward_batch, "model_runner", None), "token_to_kv_pool", None
        )
    loc = getattr(forward_batch, "out_cache_loc", None)
    if kv_pool is None or loc is None:
        print(
            f"[CGC_KV_INJECT] WARN kv_pool={kv_pool is not None} "
            f"loc={loc is not None}, skip injection",
            flush=True,
        )
        return
    import torch as _torch
    _device = kv_pool.k_buffer[0].device
    _dtype = kv_pool.dtype
    _injected = 0
    _last_seq = -1
    _skipped = 0
    # 診斷: 打印 loc 和 input_ids 長度, 定位 tokenizer 對齊問題
    _loc_len = loc.shape[0] if hasattr(loc, "shape") else len(loc)
    _fb_ids = getattr(forward_batch, "input_ids", None)
    _fb_ids_len = (_fb_ids.shape[0] if hasattr(_fb_ids, "shape") else len(_fb_ids)) if _fb_ids is not None else -1
    print(
        f"[CGC_KV_INJECT] DIAG loc_len={_loc_len} input_ids_len={_fb_ids_len} "
        f"mac_kv_len={len(mac_kv_layers)} resume_cut={resume_cut}",
        flush=True,
    )
    for layer_idx in range(0, min(resume_cut + 1, len(mac_kv_layers))):
        kv = mac_kv_layers[layer_idx]
        if kv is None:
            _skipped += 1
            continue
        k_t = kv["k"] if isinstance(kv, dict) else kv[0]
        v_t = kv["v"] if isinstance(kv, dict) else kv[1]
        # 對齊 cloud device/dtype (set_kv_buffer 內部也會轉, 但先轉避免隱式拷貝路徑分歧)
        k_t = k_t.to(device=_device, dtype=_dtype).contiguous()
        v_t = v_t.to(device=_device, dtype=_dtype).contiguous()
        # shape 守衛: loc 和 KV seq 必須匹配, 否則 set_kv_buffer 崩 (kvcache.cuh:177)
        _kv_seq = k_t.shape[0]
        if _loc_len != _kv_seq:
            print(
                f"[CGC_KV_INJECT] WARN layer {layer_idx}: loc_len={_loc_len} != kv_seq={_kv_seq}, "
                f"skip (tokenizer/forward_batch mismatch). k_shape={tuple(k_t.shape)}",
                flush=True,
            )
            _skipped += 1
            continue
        attn = self.layers[layer_idx].self_attn
        # layer_id_override 確保寫入 layer_idx slot (即使 attn.layer_id 有偏移)
        kv_pool.set_kv_buffer(
            attn, loc, k_t, v_t,
            layer_id_override=layer_idx,
        )
        _injected += 1
        _last_seq = k_t.shape[0]
    print(
        f"[CGC_KV_INJECT] injected KV for layer 0..{resume_cut} "
        f"({_injected}/{resume_cut+1} 層, skipped={_skipped}, seq={_last_seq}, "
        f"loc={tuple(loc.shape) if loc is not None else 'None'})",
        flush=True,
    )
    return _injected


def _qwen3_llm_model_forward_resume(
    self,
    input_ids: torch.Tensor,
    positions: torch.Tensor,
    forward_batch: ForwardBatch,
    input_embeds: torch.Tensor = None,
    pp_proxy_tensors: Optional[PPProxyTensors] = None,
    input_deepstack_embeds: Optional[torch.Tensor] = None,
) -> Union[torch.Tensor, PPProxyTensors]:
    """Qwen3LLMModel.forward with CGC_RESUME_FROM dispatch (VL dense-adapted).

    Dispatch point lives HERE (LLM Model layer), not in the VL wrapper, because
    Qwen3VLForConditionalGeneration.forward calls language_model via
    general_mm_embed_routine which does not thread finished_layer/hidden_states_ref
    through. Patching the LLM Model.forward is the only place where resume
    injection can intercept the layer loop.

    CGC_RESUME_FROM unset/invalid -> delegate to original forward (unchanged).
    0 <= CGC_RESUME_FROM < end_layer:
      - per-step counter (EXTEND resets, decode increments) mirrors qwen3_resume_patch
      - transport.recv(rank, step) -> DOPDResumePayloadV2 OR legacy dict
      - inject hidden_states_ref + residual_ref, skip layers 0..P-1
      - preserve input_deepstack_embeds + post_residual_addition (deepstack)

    dense vs MoE (state ABI convergence):
      - forward signature: IDENTICAL to Qwen3MoeLLMModel.forward
        (input_ids, positions, forward_batch, input_embeds, pp_proxy_tensors,
         input_deepstack_embeds) — both dense and MoE
      - layer call: IDENTICAL
        layer(positions, hs, fb, residual, post_residual_addition=deepstack_embeds)
        — dense Qwen3DecoderLayer (no router) and MoE Qwen3MoeDecoderLayer (router)
        share the same call signature; only layer-internal impl differs
      - norm call: IDENTICAL
        norm(hs, residual, post_residual_addition=last_deepstack)
      - residual format: IDENTICAL (hidden_states, residual) tuple,
        pp_proxy_tensors {"hidden_states", "residual"} keys
      - => resume injection logic is 1:1 with qwen3_vl_moe_resume_patch;
         MoE router state stays inside DecoderLayer, never leaks to LLMModel,
         so the resume consumer is model-agnostic

    VL-specific (vs qwen3_resume_patch):
      - layer call: layer(positions, hs, fb, residual,
                         post_residual_addition=deepstack_embeds)
      - norm call:  norm(hs, residual, post_residual_addition=last_deepstack)
      - signature:  extra `input_deepstack_embeds` param threaded through
    """
    _resume_cut = int(_cgc_os.environ.get("CGC_RESUME_FROM", "-1") or -1)
    _end = getattr(self, "end_layer", 10 ** 9)
    if not (0 <= _resume_cut < _end):
        return _Qwen3LLMModel_forward_orig(
            self, input_ids, positions, forward_batch, input_embeds,
            pp_proxy_tensors=pp_proxy_tensors,
            input_deepstack_embeds=input_deepstack_embeds,
        )

    global _CGC_RESUME_STEP
    _mode = (
        int(getattr(forward_batch, "forward_mode", 1))
        if forward_batch is not None
        else 1
    )
    # forward_mode.is_decode() path mirrors qwen3_resume_patch (mode==2 is decode in sglang)
    try:
        _is_decode = bool(forward_batch.forward_mode.is_decode()) if forward_batch is not None else False
    except Exception:
        _is_decode = (_mode == 2)
    if not _is_decode:  # EXTEND = start of a new request -> reset step counter
        _CGC_RESUME_STEP = 0
    _step = _CGC_RESUME_STEP
    _CGC_RESUME_STEP += 1

    _transport_mode = _cgc_os.environ.get("CGC_TRANSPORT", "mac_emit").lower()
    _transport = _cgc_get_resume_transport(_cgc_rank(), _transport_mode)
    _dtype = self.embed_tokens.weight.dtype
    # VL: input_ids may be None (uses input_embeds from vision); fallback device.
    # Mirrors qwen3_vl_moe_resume_patch input_ids None fix (health-check / vision path).
    _device = (
        (input_ids.device if input_ids is not None else None)
        or (input_embeds.device if input_embeds is not None else None)
        or (positions.device if positions is not None else None)
        or "cuda"
    )
    _hs = None
    _res = None
    _payload_finished = None
    _mac_kv = None  # CGC KV 注入: Mac 捕獲的前 P 層 RoPE 後 K/V (list[dict] 或 None)

    if _transport is not None:
        try:
            # 传 expected_seq = forward_batch input_ids 长度, 防止 warmup/capture
            # 的 1-token forward 消费 Mac 的 7-token payload (step 竞争)
            _expected_seq = None
            try:
                _fb_ids = getattr(forward_batch, "input_ids", None)
                if _fb_ids is not None and hasattr(_fb_ids, "shape"):
                    _expected_seq = int(_fb_ids.shape[0])
            except Exception:
                pass
            _raw = _transport.recv(
                _cgc_rank(), _step,
                timeout=float(_cgc_os.environ.get("CGC_RESUME_TIMEOUT", "120.0")),
                expected_seq=_expected_seq,
            )
            _dec = _cgc_decode_resume_payload(_raw)
            _payload_finished = _dec["finished_layer"]
            if _dec["hidden_states"] is not None:
                _hs = _dec["hidden_states"].to(device=_device, dtype=_dtype).contiguous()
                if _hs.dim() == 3:  # Mac 传 [1,seq,hidden] 3D, sglang 期望 [seq,hidden] 2D
                    _hs = _hs.reshape(-1, _hs.shape[-1])
            _res = _dec.get("residual")
            if _res is not None:
                _res = _res.to(device=_device, dtype=_dtype)
                if _res.dim() == 3:
                    _res = _res.reshape(-1, _res.shape[-1])
            if _res is None and _hs is not None:
                import torch as _torch_res
                _res = _torch_res.zeros_like(_hs).to(device=_device, dtype=_dtype)
            _mac_kv = _dec.get("kv_layers")  # CGC KV 注入
            # DOPD payload's resume_position overrides env CGC_RESUME_FROM if present
            if _payload_finished is not None and _payload_finished != _resume_cut:
                print(
                    f"[CGC_RESUME] NOTE env CGC_RESUME_FROM={_resume_cut} "
                    f"overridden by payload.resume_position={_payload_finished}",
                    flush=True,
                )
                _resume_cut = int(_payload_finished)
            print(
                f"[CGC_RESUME] (dense) from={_resume_cut} step={_step} rank={_cgc_rank()} "
                f"mode={_mode} loaded hidden_states "
                f"[{tuple(_hs.shape) if _hs is not None else 'None'}] "
                f"<- {_transport_mode} transport "
                f"(abi={bool(_dec['abi_descriptor'])}, "
                f"model_type={_dec['abi_descriptor'].get('model_type', 'unknown')})",
                flush=True,
            )
        except Exception as _e:
            print(
                f"[CGC_RESUME] (dense) WARN from={_resume_cut} step={_step} "
                f"rank={_cgc_rank()} mode={_mode} transport recv failed "
                f"({_e!r}), full forward fallback",
                flush=True,
            )
    else:
        _p = (
            f"{_cgc_os.environ.get('CGC_HANDOFF_PATH', '/data/cgc_handoff.pt')}"
            f".rank{_cgc_rank()}.step{_step}"
        )
        if _cgc_os.path.exists(_p):
            try:
                _raw = torch.load(_p, map_location=_device, weights_only=True)
                _dec = _cgc_decode_resume_payload(_raw)
                _payload_finished = _dec["finished_layer"]
                if _dec["hidden_states"] is not None:
                    _hs = _dec["hidden_states"].to(device=_device, dtype=_dtype).contiguous()
                _res = _dec.get("residual")
                if _res is not None:
                    _res = _res.to(device=_device, dtype=_dtype)
                if _res is None and _hs is not None:
                    import torch as _torch_res
                    _res = _torch_res.zeros_like(_hs).to(device=_device, dtype=_dtype)
                _mac_kv = _dec.get("kv_layers")  # CGC KV 注入
                if _payload_finished is not None and _payload_finished != _resume_cut:
                    _resume_cut = int(_payload_finished)
                print(
                    f"[CGC_RESUME] (dense) from={_resume_cut} step={_step} rank={_cgc_rank()} "
                    f"mode={_mode} loaded hidden_states "
                    f"[{tuple(_hs.shape) if _hs is not None else 'None'}] <- {_p}",
                    flush=True,
                )
            except Exception as _e:
                print(
                    f"[CGC_RESUME] (dense) WARN file load failed: {_e!r}, full forward fallback",
                    flush=True,
                )
        else:
            print(
                f"[CGC_RESUME] (dense) WARN from={_resume_cut} step={_step} "
                f"rank={_cgc_rank()} mode={_mode} step file missing, "
                f"full forward fallback",
                flush=True,
            )

    # --- inject hidden_states (skip embed) or full forward fallback (health-check/no Mac emit) ---
    if _hs is None:
        # health-check or no Mac emit: full forward fallback (skip resume, avoid pp_group None)
        # This mirrors the MoE patch's health-check fallback: when no hidden_states
        # arrive (e.g. sglang server health-check probe, no Mac emit), delegate to
        # the original forward instead of trying to resume from nothing.
        print(
            f"[CGC_RESUME] (dense) no hidden_states (health-check/no Mac emit), "
            f"full forward fallback step={_step} rank={_cgc_rank()}",
            flush=True,
        )
        return _Qwen3LLMModel_forward_orig(
            self, input_ids, positions, forward_batch, input_embeds,
            pp_proxy_tensors=pp_proxy_tensors,
            input_deepstack_embeds=input_deepstack_embeds,
        )
    hidden_states = _hs

    # --- inject residual (Qwen3 VL dense layer needs both hs + residual, same as MoE) ---
    if _res is not None:
        residual = _res
    elif self.pp_group.is_first_rank:
        residual = None
    elif pp_proxy_tensors is not None:
        residual = pp_proxy_tensors.get("residual")
    else:
        residual = None

    # --- layer loop with deepstack (VL-specific: post_residual_addition) ---
    # Identical to MoE: layer(positions, hs, fb, residual, post_residual_addition=ds)
    # dense Qwen3DecoderLayer has same external signature as MoE Qwen3MoeDecoderLayer.
    aux_hidden_states = []
    loop_start = max(self.start_layer, int(_resume_cut) + 1)
    # === CGC KV 注入: 把 Mac 捕獲的前 P 層 KV 寫入 cloud KV cache (layer 0.._resume_cut) ===
    # 修 step8 KV cache 崩: 補滿前 P 層 KV slot, 使 layer P..end attention 能正確讀取。
    # 設計見 CGC_Phase2/kv_injection_design.md §4。只在 EXTEND 注入 (decode 方案 B 待後續)。
    if _mac_kv:
        _kv_injected = _cgc_inject_prefill_kv(self, forward_batch, _mac_kv, _resume_cut)
        if _kv_injected == 0:
            # KV 注入 0 層 (seq 不匹配/tokenizer 差異) → resume 會讀空 KV 崩, fallback full forward
            print(
                f"[CGC_RESUME] (dense) KV 注入 0 層 (Mac/cloud seq 不匹配), "
                f"fallback full forward step={_step} rank={_cgc_rank()}",
                flush=True,
            )
            return _Qwen3LLMModel_forward_orig(
                self, input_ids, positions, forward_batch, input_embeds,
                pp_proxy_tensors=pp_proxy_tensors,
                input_deepstack_embeds=input_deepstack_embeds,
            )
    for layer_idx in range(loop_start, self.end_layer):
        if layer_idx in getattr(self, "layers_to_capture", []):
            aux_hidden_states.append(
                hidden_states + residual if residual is not None else hidden_states
            )
        # SGLang applies residual at START of next layer; deepstack must be
        # added AFTER residual: (hidden_states + residual) + deepstack.
        # Deepstack for prev_layer is applied at start of current layer via
        # post_residual_addition (VL-specific, preserved on resume path).
        deepstack_embeds = self.get_deepstack_embeds(
            layer_idx - 1, input_deepstack_embeds
        )
        hidden_states, residual = self.layers[layer_idx](
            positions,
            hidden_states,
            forward_batch,
            residual,
            post_residual_addition=deepstack_embeds,
        )

    # Handle deepstack for the last processed layer if it exists.
    last_deepstack = self.get_deepstack_embeds(
        self.end_layer - 1, input_deepstack_embeds
    )

    if not self.pp_group.is_last_rank:
        return PPProxyTensors(
            {
                "hidden_states": hidden_states,
                "residual": residual,
            }
        )
    else:
        if hidden_states.shape[0] != 0:
            if residual is None:
                hidden_states = self.norm(hidden_states)
            else:
                hidden_states, _ = self.norm(
                    hidden_states, residual, post_residual_addition=last_deepstack
                )

    if len(aux_hidden_states) == 0:
        return hidden_states

    return hidden_states, aux_hidden_states


# Wire the resume forward in (non-resume still delegates to the saved original).
Qwen3LLMModel.forward = _qwen3_llm_model_forward_resume
# === end CGC Qwen3-VL dense resume patch ====================================
'''

MARKER = "_CGC_PATCH_MARKER = \"cgc_qwen3_vl_resume_v1\""
DEFAULT_TARGET = (
    "/usr/local/lib/python3.12/dist-packages/sglang/srt/models/qwen3_vl.py"
)


def _is_patched(src: str) -> bool:
    return "_CGC_PATCH_MARKER" in src or "CGC Qwen3-VL dense resume patch" in src


def apply(target: str, dry_run: bool = False) -> int:
    with open(target, "r", encoding="utf-8") as f:
        src = f.read()

    if _is_patched(src):
        print(f"[skip] {target} 已含 CGC resume patch marker, 跳过")
        return 0

    # backup
    ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    bak = f"{target}.bak.{ts}"
    shutil.copy2(target, bak)
    print(f"[backup] {target} -> {bak}")

    patched = src.rstrip() + "\n" + PATCH_BLOCK

    if dry_run:
        print(f"[dry-run] would write {len(patched)} bytes to {target}")
        return 0

    with open(target, "w", encoding="utf-8") as f:
        f.write(patched)
    print(f"[patched] {target} (+{len(PATCH_BLOCK)} bytes)")
    print(
        "[note] 确保云端 cgc_handoff_transport.py 在 qwen3_vl.py 同目录或 sys.path; "
        "启动 sglang server 时设 CGC_RESUME_FROM=P CGC_TRANSPORT=mac_emit"
    )
    return 0


def revert(target: str) -> int:
    import glob

    with open(target, "r", encoding="utf-8") as f:
        src = f.read()

    if not _is_patched(src):
        print(f"[skip] {target} 未含 patch marker, 无需 revert")
        return 0

    idx = src.find("# === CGC Qwen3-VL dense resume patch (auto-generated by cgc_engine)")
    if idx < 0:
        print(f"[warn] 找不到 patch 起始标记, 改用最近 backup 恢复")
    else:
        head = src[:idx].rstrip() + "\n"
        with open(target, "w", encoding="utf-8") as f:
            f.write(head)
        print(f"[reverted] {target} (移除 patch block)")
        return 0

    baks = sorted(glob.glob(f"{target}.bak.*"))
    if not baks:
        print(f"[error] 无 backup 文件可恢复: {target}.bak.*")
        return 1
    shutil.copy2(baks[-1], target)
    print(f"[reverted] {target} <- {baks[-1]}")
    return 0


def main():
    import argparse

    ap = argparse.ArgumentParser(description="CGC Qwen3-VL dense resume patch (sglang-native)")
    ap.add_argument(
        "--target", default=DEFAULT_TARGET,
        help=f"qwen3_vl.py 路径 (默认 {DEFAULT_TARGET})",
    )
    ap.add_argument("--revert", action="store_true", help="移除 patch (恢复原文件)")
    ap.add_argument("--dry-run", action="store_true", help="只打印不写")
    args = ap.parse_args()

    if not os.path.exists(args.target):
        print(f"[error] target 不存在: {args.target}")
        return 2

    if args.revert:
        return revert(args.target)
    return apply(args.target, dry_run=args.dry_run)


if __name__ == "__main__":
    sys.exit(main())
